CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE map (_id     INTEGER   PRIMARY KEY ON CONFLICT FAIL AUTOINCREMENT,name    CHAR (40),type    CHAR (20) NOT NULL ON CONFLICT FAIL,floor   INTEGER   NOT NULL ON CONFLICT FAIL,value   BLOB      NOT NULL ON CONFLICT FAIL,map_md5 CHAR (40) NOT NULL ON CONFLICT FAIL,floorInfo CHAR,buildingInfo CHAR);
CREATE UNIQUE INDEX unique_map ON map (type, floor);
CREATE TABLE AbilityTable(_id                 INTEGER PRIMARY KEY AUTOINCREMENT,robot_type          CHAR (20) NOT NULL,ability_type        CHAR (20) NOT NULL,message             TEXT);
CREATE TABLE build_map_type (_id     INTEGER   PRIMARY KEY ON CONFLICT FAIL AUTOINCREMENT,name    CHAR (40) NOT NULL ON CONFLICT FAIL,type    CHAR (20) );
CREATE UNIQUE INDEX unique_build_type ON build_map_type (name);
CREATE TABLE dynamic_map (_id     INTEGER   PRIMARY KEY ON CONFLICT FAIL AUTOINCREMENT,name    CHAR (40),type    CHAR (20) NOT NULL ON CONFLICT FAIL,floor   INTEGER   NOT NULL ON CONFLICT FAIL,value   BLOB      NOT NULL ON CONFLICT FAIL,map_md5 CHAR (40) NOT NULL ON CONFLICT FAIL,floorInfo CHAR,buildingInfo CHAR,width   INTEGER,height  INTEGER,originx  REAL,originy  REAL);
CREATE UNIQUE INDEX unique_dynamic_map ON dynamic_map (type, floor);
CREATE TABLE pose(_id           INTEGER   PRIMARY KEY AUTOINCREMENT,target_id     INTEGER   NOT NULL ON CONFLICT FAIL UNIQUE ON CONFLICT FAIL,name          CHAR (30),type          CHAR (20) NOT NULL ON CONFLICT FAIL,floor         INTEGER   NOT NULL ON CONFLICT FAIL,phone         INTEGER,map_md5       CHAR (40),elevator_id   INTEGER,position_x    REAL      NOT NULL ON CONFLICT FAIL,position_y    REAL      NOT NULL ON CONFLICT FAIL,position_z    REAL      NOT NULL ON CONFLICT FAIL,orientation_x REAL      NOT NULL ON CONFLICT FAIL,orientation_y REAL      NOT NULL ON CONFLICT FAIL,orientation_z REAL      NOT NULL ON CONFLICT FAIL,orientation_w REAL      NOT NULL ON CONFLICT FAIL,floorInfo   CHAR,buildingInfo   CHAR,macAddress  CHAR,disableOrientation  INTEGER,phoneStr CHAR,config CHAR,isDefaultCharge INTEGER,business_type CHAR);
CREATE TABLE web_app_data(_id           INTEGER   PRIMARY KEY AUTOINCREMENT,target_id     INTEGER   NOT NULL ON CONFLICT FAIL UNIQUE ON CONFLICT FAIL,name          CHAR (30),type          CHAR (20) NOT NULL ON CONFLICT FAIL,subType       CHAR (20) NOT NULL ON CONFLICT FAIL,floor         INTEGER   NOT NULL ON CONFLICT FAIL,phone         INTEGER,map_md5       CHAR (40),elevator_id   INTEGER,position_x    REAL      NOT NULL ON CONFLICT FAIL,position_y    REAL      NOT NULL ON CONFLICT FAIL,position_z    REAL      NOT NULL ON CONFLICT FAIL,orientation_x REAL      NOT NULL ON CONFLICT FAIL,orientation_y REAL      NOT NULL ON CONFLICT FAIL,orientation_z REAL      NOT NULL ON CONFLICT FAIL,orientation_w REAL      NOT NULL ON CONFLICT FAIL,floorInfo   CHAR,buildingInfo   CHAR,macAddress  CHAR,disableOrientation  INTEGER,phoneStr CHAR,config CHAR,value CHAR,isDefaultCharge INTEGER);
CREATE TABLE init_pose (_id           INTEGER PRIMARY KEY AUTOINCREMENT,init_id       INTEGER UNIQUE,base_map      CHAR,init_method   CHAR,angleRange    REAL,confidence    REAL,penetrate     REAL,position_x    REAL,position_y    REAL,position_z    REAL,orientation_x REAL,orientation_y REAL,orientation_z REAL,orientation_w REAL);
CREATE TABLE label (_id           INTEGER PRIMARY KEY AUTOINCREMENT,label_id      INTEGER,base_map      CHAR,floor         INTEGER,position_x    REAL,position_y    REAL,position_z    REAL,orientation_x REAL,orientation_y REAL,orientation_z REAL,orientation_w REAL);
CREATE UNIQUE INDEX unique_label ON label (label_id, floor);
CREATE TABLE vslamKeyframe(_id           INTEGER   PRIMARY KEY AUTOINCREMENT,id            INTEGER   NOT NULL ON CONFLICT FAIL,floor         INTEGER   NOT NULL ON CONFLICT FAIL,position_x    REAL      NOT NULL ON CONFLICT FAIL,position_y    REAL      NOT NULL ON CONFLICT FAIL,position_yaw  REAL      NOT NULL ON CONFLICT FAIL,number        INTEGER   NOT NULL ON CONFLICT FAIL,pose_id       INTEGER   NOT NULL ON CONFLICT FAIL,value         BLOB      NOT NULL ON CONFLICT FAIL);
CREATE UNIQUE INDEX unique_vslamKeyframe ON vslamKeyframe (id, floor);
CREATE TABLE gate (_id            INTEGER PRIMARY KEY AUTOINCREMENT,id             INTEGER UNIQUE,floor          INTEGER,mac_address    CHAR);
CREATE TABLE zone(_id                 INTEGER PRIMARY KEY AUTOINCREMENT,zoneId              INTEGER NOT NULL UNIQUE,zoneMd5             CHAR (40),zoneType            CHAR (20),zoneCoordsPoints    TEXT NOT NULL,floor               INTEGER,mapMd5              CHAR (40),name                CHAR (20),parentId            INTEGER,zoneArea            REAL,material            CHAR (40));
CREATE TABLE path(_id                 INTEGER PRIMARY KEY AUTOINCREMENT,pathId              INTEGER not null,pathMd5             CHAR(40),zoneId              INTEGER,parentId            INTEGER,floor               INTEGER,pathType            CHAR(20),pathValue           TEXT,foreign key (zoneId) references zone(zoneId));
CREATE TABLE commonArea(_id                 INTEGER PRIMARY KEY AUTOINCREMENT,areaId              INTEGER NOT NULL UNIQUE,floor               INTEGER,type                CHAR (20),areaShape           CHAR (20),areaCoordsPoints    TEXT NOT NULL,areaName            CHAR (20));
CREATE TABLE commonPath (_id            INTEGER PRIMARY KEY AUTOINCREMENT,id             INTEGER UNIQUE,floor          INTEGER,type           CHAR (20) NOT NULL ON CONFLICT FAIL,value          CHAR);
CREATE TABLE semantic_map (_id    INTEGER PRIMARY KEY AUTOINCREMENT,id     INTEGER,floor  INTEGER,name   CHAR,bindPosId  INTEGER,posNum INTEGER,x      REAL  NOT NULL ON CONFLICT FAIL,y      REAL  NOT NULL ON CONFLICT FAIL,z      REAL  NOT NULL ON CONFLICT FAIL);
CREATE TABLE keyframe (_id           INTEGER PRIMARY KEY AUTOINCREMENT,keyframe_id      INTEGER,base_map            CHAR,db_key_sn           CHAR,db_key_time         CHAR,db_key_sub_db_desc  CHAR,floor         REAL,confidence    INTEGER,position_x    REAL,position_y    REAL,position_z    REAL,orientation_x REAL,orientation_y REAL,orientation_z REAL,orientation_w REAL);
CREATE UNIQUE INDEX unique_keyframe ON keyframe (keyframe_id, floor);
CREATE TABLE elevator (_id               INTEGER PRIMARY KEY AUTOINCREMENT,elevator_id       INTEGER UNIQUE,robot_id          INTEGER,available_floor   CHAR,transit_floor     CHAR,opendoor_time     INTEGER);
CREATE TABLE RobotPos (floor         Int,validFlag     INTEGER,position_x    REAL,position_y    REAL,position_z    REAL,orientation_x REAL,orientation_y REAL,orientation_z REAL,orientation_w REAL);
CREATE TABLE RobotSensorData (sensorData      REAL);
